@push('scripts')
<script>document.addEventListener('DOMContentLoaded',()=>{const invoice=document.getElementById('paymentInvoice');const amount=document.getElementById('paymentAmount');const student=document.getElementById('paymentStudentId');const monthly=document.getElementById('monthlyFeeAmount');const balanceOut=document.getElementById('invoiceBalanceDisplay');const receivedOut=document.getElementById('receivedDisplay');const remainingOut=document.getElementById('remainingDisplay');const label=document.getElementById('selectedInvoiceLabel');const money=new Intl.NumberFormat('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});const update=()=>{const option=invoice?.selectedOptions[0];const balance=Number(option?.dataset.balance)||0;const received=Math.max(Number(amount?.value)||0,0);if(student)student.value=option?.dataset.student||'';if(monthly)monthly.value=balance.toFixed(2);if(amount)amount.max=balance.toFixed(2);if(label)label.textContent=option?.dataset.name?`${option.dataset.name} · ${option.dataset.month}`:'Invoice Outstanding';if(balanceOut)balanceOut.textContent=`Rs ${money.format(balance)}`;if(receivedOut)receivedOut.textContent=`Rs ${money.format(received)}`;if(remainingOut)remainingOut.textContent=`Rs ${money.format(Math.max(balance-received,0))}`;};invoice?.addEventListener('change',update);amount?.addEventListener('input',update);update();});</script>
@endpush
